"""
Centralized SaaS Global AIOps Engine.
Performs cross-service incident correlation, root cause analysis (RCA),
alert clustering, and health scoring strictly using anonymized metadata digests.
"""

import time
import uuid
from typing import List, Dict, Any, Optional
from collections import defaultdict
from common.models import EgressEnvelope, EdgeAlert, HealthMetric


class CorrelatedIncident:
    """Consolidated incident generated by cross-correlating edge alerts and health metrics."""

    def __init__(
        self,
        incident_id: str,
        tenant_id: str,
        title: str,
        severity: str,
        probable_root_cause: str,
        affected_services: List[str],
        contributing_alerts: List[Dict[str, Any]],
        recommended_action: str
    ):
        self.incident_id = incident_id
        self.tenant_id = tenant_id
        self.title = title
        self.severity = severity
        self.probable_root_cause = probable_root_cause
        self.affected_services = affected_services
        self.contributing_alerts = contributing_alerts
        self.recommended_action = recommended_action
        self.created_at = time.time()

    def to_dict(self) -> Dict[str, Any]:
        return {
            "incident_id": self.incident_id,
            "tenant_id": self.tenant_id,
            "title": self.title,
            "severity": self.severity,
            "probable_root_cause": self.probable_root_cause,
            "affected_services": self.affected_services,
            "contributing_alert_count": len(self.contributing_alerts),
            "contributing_alerts": self.contributing_alerts,
            "recommended_action": self.recommended_action,
            "created_at": self.created_at
        }


class GlobalAIOpsEngine:
    """Centralized SaaS intelligence layer operating across isolated tenant streams."""

    # Simplified service dependency topology graph: upstream -> downstream
    TOPOLOGY = {
        "checkout-api": ["payment-service", "inventory-service"],
        "payment-service": ["postgres-db", "external-stripe-proxy"],
        "inventory-service": ["redis-cache", "postgres-db"]
    }

    def __init__(self):
        # tenant_id -> list of envelopes
        self.tenant_envelopes: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
        # tenant_id -> list of incidents
        self.tenant_incidents: Dict[str, List[CorrelatedIncident]] = defaultdict(list)
        # Statistics
        self.total_envelopes_received = 0
        self.total_raw_bytes_prevented_from_egress = 0

    def ingest_envelope(self, envelope_dict: Dict[str, Any]) -> List[CorrelatedIncident]:
        """Process an approved egress envelope and run correlation algorithms."""
        tenant_id = envelope_dict["tenant_id"]
        self.tenant_envelopes[tenant_id].append(envelope_dict)
        self.total_envelopes_received += 1

        # Track privacy metrics
        summaries = envelope_dict.get("summaries") or {}
        raw_bytes = summaries.get("raw_bytes_retained_locally", 0)
        self.total_raw_bytes_prevented_from_egress += raw_bytes

        # Extract alerts and health metrics
        alerts = envelope_dict.get("alerts", [])
        health_metrics = envelope_dict.get("health_indicators", [])

        # Run multi-signal correlation
        new_incidents = self._correlate_signals(tenant_id, alerts, health_metrics)
        self.tenant_incidents[tenant_id].extend(new_incidents)
        return new_incidents

    def _correlate_signals(
        self,
        tenant_id: str,
        alerts: List[Dict[str, Any]],
        health_metrics: List[Dict[str, Any]]
    ) -> List[CorrelatedIncident]:
        """Correlate multiple isolated edge alerts into unified root-cause incidents."""
        if not alerts:
            return []

        incidents: List[CorrelatedIncident] = []
        affected_services = list(set(a.get("service", "unknown") for a in alerts))

        # Check for cascading database/dependency failure pattern
        has_db_issue = any("db" in a.get("service", "").lower() or "postgres" in a.get("service", "").lower() for a in alerts)
        has_api_issue = any("api" in a.get("service", "").lower() or "checkout" in a.get("service", "").lower() for a in alerts)

        if has_db_issue and has_api_issue:
            # Causal inference: Upstream database latency propagates to downstream API
            incidents.append(CorrelatedIncident(
                incident_id=f"INC-{uuid.uuid4().hex[:6].upper()}",
                tenant_id=tenant_id,
                title="Cascading Service Degradation: Database Bottleneck impacting Checkout API",
                severity="CRITICAL",
                probable_root_cause="postgres-db connection pool exhaustion / slow query lock",
                affected_services=affected_services,
                contributing_alerts=alerts,
                recommended_action="Scale DB read replicas or increase connection pool limit on db-proxy."
            ))
        elif alerts:
            # Group alerts by primary service
            primary_svc = alerts[0].get("service", "core-service")
            max_sev = "CRITICAL" if any(a.get("severity") == "CRITICAL" for a in alerts) else "WARNING"
            incidents.append(CorrelatedIncident(
                incident_id=f"INC-{uuid.uuid4().hex[:6].upper()}",
                tenant_id=tenant_id,
                title=f"AIOps Cluster Anomaly detected on {primary_svc}",
                severity=max_sev,
                probable_root_cause=f"{primary_svc} - {alerts[0].get('rule_or_model', 'Statistical Anomaly')}",
                affected_services=affected_services,
                contributing_alerts=alerts,
                recommended_action=alerts[0].get("suggested_runbook", "Check service telemetry and local logs")
            ))

        return incidents

    def compute_tenant_health_index(self, tenant_id: str) -> float:
        """Calculate overall 0-100% operational health score for tenant."""
        envelopes = self.tenant_envelopes.get(tenant_id, [])
        if not envelopes:
            return 100.0

        latest = envelopes[-1]
        metrics = latest.get("health_indicators", [])
        if not metrics:
            return 100.0

        scores = []
        for m in metrics:
            status = m.get("status", "HEALTHY")
            if status == "HEALTHY":
                scores.append(100.0)
            elif status == "DEGRADED":
                scores.append(70.0)
            else:  # CRITICAL
                scores.append(25.0)

        return round(sum(scores) / len(scores), 1)

    def get_dashboard_state(self, tenant_id: str) -> Dict[str, Any]:
        """Return state for dashboard rendering."""
        envelopes = self.tenant_envelopes.get(tenant_id, [])
        latest_envelope = envelopes[-1] if envelopes else None
        incidents = [i.to_dict() for i in self.tenant_incidents.get(tenant_id, [])]
        health_index = self.compute_tenant_health_index(tenant_id)

        return {
            "tenant_id": tenant_id,
            "overall_health_score": health_index,
            "total_envelopes_ingested": len(envelopes),
            "total_raw_bytes_kept_local": self.total_raw_bytes_prevented_from_egress,
            "privacy_compliance_score": "100% (Zero Raw Data Egress)",
            "active_incidents": incidents[-5:],  # latest 5
            "latest_health_metrics": latest_envelope.get("health_indicators", []) if latest_envelope else [],
            "latest_summaries": latest_envelope.get("summaries", {}) if latest_envelope else {},
            "latest_alerts": latest_envelope.get("alerts", []) if latest_envelope else []
        }
